    drawdowns = max_drawdown(_returns(given["returns"]))
    assert all(isinstance(d, Drawdown) for d in drawdowns)
    assert [d.ticker for d in drawdowns] == [row["ticker"] for row in expected["drawdowns"]]


@pytest.mark.intent
def test_tc08_depth(golden):
    given, expected = golden("risk", "TC-08")
    got = _by_ticker(max_drawdown(_returns(given["returns"])))
