    row = next(r for r in expected["drawdowns"] if r["ticker"] == "Z")
    assert z.peak_date == returns.base_date
    assert z.peak_date == row["peak_date"]
    assert z.trough_date == row["trough_date"]


@pytest.mark.intent
def test_contract_sample_meets_drawdown_invariants():
    data = json.loads((CONTRACTS / "risk.Returns" / "sample.json").read_text())
    returns = _returns(data)
    calendar = (returns.base_date, *returns.dates)
